from fastapi.testclient import TestClient
from app.main import app
def test_transition_lifecycle():
 c=TestClient(app); n=c.post('/api/novels',json={'title':'转场'}).json(); nid=n['id']; c.post(f'/api/novels/{nid}/chapters',json={'title':'一','content':'a'}); c.post(f'/api/novels/{nid}/chapters',json={'title':'二','content':'b'}); s=c.post(f'/api/novels/{nid}/screenplays',json={}).json(); u=f"/api/novels/{nid}/screenplays/{s['id']}"; c.post(u+'/approve'); c.post(u+'/shots'); c.post(u+'/shots/approve'); planned=c.post(u+'/transitions').json(); assert 'transitions' in planned; tid=planned['transitions'][0]['id']; updated=c.put(u+f'/transitions/{tid}',json={'type':'DISSOLVE','duration_seconds':2,'note':'时间跳跃','prompt':'旧 Prompt'}).json(); assert updated['transitions'][0]['prompt_status']=='EDITED'; generated=c.get(u+f'/transitions/{tid}/prompt'); assert generated.status_code==200; assert 'DISSOLVE' in generated.json()['prompt']; approved=c.post(u+'/transitions/approve'); assert approved.status_code==200; assert approved.json()['transitions'][0]['prompt_status']=='FROZEN'
